module Kernel.External.SMS.CerfSms.Config where

import Kernel.External.Encryption
import Kernel.Prelude

-- | CERF CPaaS exposes the same push service over two wire formats. Which one a
-- merchant is provisioned for is decided by CERF, so it is part of the config.
data CerfSmsTransport
  = -- | @GET \/pushapi\/sendmsg@ with query params.
    CerfHttpPush
  | -- | @POST \/pushapi\/json\/sendbulkmsg@ with a JSON body. Only this one
    -- carries the DLT @entityid@ \/ @templateid@ pair.
    CerfJsonPush
  deriving (Show, Eq, Generic, ToJSON, FromJSON)

data CerfSmsCfg = CerfSmsCfg
  { username :: Text,
    -- | Sent as @apikey@ on the push API and as @password@ on the JSON API.
    apiKey :: EncryptedField 'AsEncrypted Text,
    transport :: CerfSmsTransport,
    -- | DLT entity id. Only used by 'CerfJsonPush'.
    entityId :: Maybe Text,
    -- | Auto-generated by CERF for the day when absent.
    campaignName :: Maybe Text,
    -- | Customer reference key, echoed back on the response.
    custRef :: Maybe Text,
    -- | Used when the caller does not specify one. @PM@ (plain) or @UC@ (unicode).
    defaultMessageType :: Text,
    url :: BaseUrl
  }
  deriving (Show, Eq, Generic, ToJSON, FromJSON)
